// Rust-only immutable source-manifest + seven-file Git blob admission.
// No guest source is executed, no LLVM IR is generated by this tool.
use std::{
    fs,
    io::Write,
    path::Path,
    process::{Command, Stdio},
};

const CORPUS_GIT_BLOB: &str = "526595b444aaf761dc75c44ad9b39a08d45341aa";
const UNITS: [(&str, &str); 7] = [
    (".atto.pkg.toml", "500be9437a53a6767002280d60507587c947b92c"),
    ("src/counter/actor.atto", "5135f72fac5b9ccb5c2a418f0d9f79bdd3f5ea32"),
    ("src/counter/contract.atto", "213541736c415d30fc54bc0f413d8b0f77b623e4"),
    ("src/counter/main.atto", "90d33cf97bfe553021cf340af8f62e4036a884e1"),
    ("src/counter/method.atto", "e7efbde0987013bc231eef40ec0524eeadc636e8"),
    ("src/counter/receive.atto", "0c5fc9d696df0716bdc73daefa43482a1255fba2"),
    ("src/counter/state.atto", "5a63c3a307ec47e19025848fb979ceb42e9980c5"),
];

fn git_blob(data: &[u8]) -> Result<String, String> {
    let mut child = Command::new("git")
        .args(["hash-object", "--stdin"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| format!("cannot launch git hash-object: {e}"))?;
    child
        .stdin
        .take()
        .ok_or("git stdin absent")?
        .write_all(data)
        .map_err(|e| format!("git stdin write failed: {e}"))?;
    let result = child
        .wait_with_output()
        .map_err(|e| format!("git hash failed: {e}"))?;
    if !result.status.success() {
        return Err(format!(
            "git hash failed: {}",
            String::from_utf8_lossy(&result.stderr)
        ));
    }
    let hash = String::from_utf8(result.stdout)
        .map_err(|e| format!("invalid git output: {e}"))?;
    let hash = hash.trim();
    if hash.len() != 40 || !hash.bytes().all(|b| b.is_ascii_hexdigit()) {
        return Err("git returned invalid blob SHA".into());
    }
    Ok(hash.into())
}

fn check_bytes(data: &[u8], expected: &str) -> Result<(), String> {
    if data.is_empty()
        || data.len() > 65_536
        || data.starts_with(&[0xef, 0xbb, 0xbf])
        || data.contains(&0)
        || std::str::from_utf8(data).is_err()
    {
        return Err("invalid UTF-8, BOM, NUL or oversized Counter unit".into());
    }
    if git_blob(data)? != expected {
        return Err("canonical Counter v2 source Git blob mismatch".into());
    }
    Ok(())
}

fn verify(root: &Path) -> Result<(), String> {
    for directory in [
        root.to_path_buf(),
        root.join("src"),
        root.join("src/counter"),
    ] {
        let kind = fs::symlink_metadata(&directory)
            .map_err(|_| "Counter source directory cannot be inspected")?
            .file_type();
        if !kind.is_dir() || kind.is_symlink() {
            return Err("Counter source directory must not be a symlink".into());
        }
    }
    let manifest_path = root.join("corpus.json");
    let manifest_type = fs::symlink_metadata(&manifest_path)
        .map_err(|e| format!("cannot stat Counter manifest: {e}"))?
        .file_type();
    if !manifest_type.is_file() || manifest_type.is_symlink() {
        return Err("Counter manifest must be real regular file".into());
    }
    check_bytes(
        &fs::read(&manifest_path)
            .map_err(|e| format!("cannot read Counter manifest: {e}"))?,
        CORPUS_GIT_BLOB,
    )?;

    for (name, sha) in UNITS {
        let path = root.join(name);
        let file_type = fs::symlink_metadata(&path)
            .map_err(|e| format!("cannot stat Counter source unit {name}: {e}"))?
            .file_type();
        if !file_type.is_file() || file_type.is_symlink() {
            return Err(format!("Counter source unit is not real file: {name}"));
        }
        let bytes = fs::read(&path)
            .map_err(|e| format!("cannot read Counter source unit {name}: {e}"))?;
        check_bytes(&bytes, sha).map_err(|e| format!("{name}: {e}"))?;

        // Tampering with any source byte must lose the Git blob identity.
        let mut mutated = bytes.clone();
        mutated[0] ^= 1;
        if check_bytes(&mutated, sha).is_ok() {
            return Err(format!("Counter unit tampering escaped admission: {name}"));
        }
    }

    let main_dir = root.join("src/counter");
    let mut source_count = 0usize;
    for entry in fs::read_dir(&main_dir)
        .map_err(|e| format!("cannot enumerate Counter source package: {e}"))?
    {
        let entry = entry.map_err(|_| "invalid Counter package directory entry")?;
        let kind = entry
            .file_type()
            .map_err(|_| "cannot inspect Counter package directory entry")?;
        if !kind.is_file() || kind.is_symlink() {
            return Err("Counter package contains unexpected non-file entry".into());
        }
        source_count += 1;
    }
    if source_count != 6 {
        return Err("Counter v2 package contains unexpected source entries".into());
    }
    Ok(())
}

fn main() -> Result<(), String> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../contracts/actor-counter-identical-source-v1");
    verify(&root)?;
    println!(
        "LLVM_COUNTER_V2_SOURCE_PIN_PASS corpus={} units=7 negative_mutations=7 guest_executed=false",
        CORPUS_GIT_BLOB
    );
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn all_seven_source_units_have_unique_paths_and_git_hashes() {
        let mut paths = std::collections::HashSet::new();
        let mut hashes = std::collections::HashSet::new();
        for (path, sha) in UNITS {
            assert!(paths.insert(path), "duplicate source path");
            assert!(hashes.insert(sha), "duplicate source hash");
            assert_eq!(sha.len(), 40);
            assert!(sha.bytes().all(|b| b.is_ascii_hexdigit()));
        }
    }

    #[test]
    fn reject_empty_bom_nul_and_non_utf8() {
        for candidate in [
            Vec::new(),
            b"\xef\xbb\xbf".to_vec(),
            b"abc\x00".to_vec(),
            vec![0xff, 0xff],
        ] {
            assert!(check_bytes(&candidate, CORPUS_GIT_BLOB).is_err());
        }
    }
}
